// Check if bitmap is full
    if (bitmap_full(bitmap, binfo)) {
        return BITMAP_MAXBITS;
    }

    // Find first unset bit
    size_t bit = 0;
    size_t group = 0;
    size_t level = 0;
    size_t offset = 0;

    // Use the bitmap tree structure to find the first unset bit
    while (level < binfo->nlevels) {
        // Calculate the group index for current level
        size_t group_idx = group + binfo->levels[level].ngroups;

        // Check if the group is all set
        if (bitmap[group_idx] != ~bitmap_t(0)) {
            // Find the first unset bit in this group
            size_t group_bit = ffs_lu(~bitmap[group_idx]);
            bit = group * BITMAP_GROUP_NBITS + group_bit;
            break;
        }

        // Move to next level
        group = group_idx;
        level++;
    }

    // If we didn't find it in the tree, do a linear search
    if (level == binfo->nlevels) {
        for (size_t i = 0; i < binfo->nbits; i++) {
            if (!bitmap_get(bitmap, binfo, i)) {
                bit = i;
                break;
            }
        }
    }

    // Atomically set the bit
    bitmap_set(bitmap, binfo, bit);

    return bit;

